    "extracto": "D3IN104 Humedad activa en arcos en mampostería 1.20 D3IN127 INFILTRACIÓN LOSA Tipo de daño/calificaci ón Calificación Insignific ante (0) Ligero (1) Leve (2) Fuerte (3) Severo (4) Extremo (5) D3IN104 Humedad activa en arcos en mampostería Este tipo de daño se presenta más especialmente en los arcos de mampostería. Muchas veces dicha descomposición es ocasionada por la acumulación de agua en exceso que genera desintegración del material y afecta apreciablemente su durabilidad. La saturación de humedad en el interior de la mampostería no solo contribuye a la degradación del ladrillo y los morteros, sino que desintegra los componentes de estos últimos por lavado de los más finos e hincha los suelos de relleno afectando la estabilidad de la estructura. Fuente:(Galindo & Paredes, 2008) y (E. Muñoz, 2012) No presenta . Cuando la extensión del área de humedad activa es menor al 10% Cuando la extensión del área de humedad activa entre el 10+-30% o hay otros daños de gravedad asociados. . Cuando la extensión del área de humedad activa entre el 30-40% o hay otros daños de gravedad asociados.. Cuando la extensión del área de humedad activa entre el 40-50% o hay otros daños de gravedad asociados. Cuando la extensión del área de humedad activa es mayor al 50% o hay otros daños de extrema gravedad asociados.",
