    "pagina": 51,
    "extracto": "D6DC45 DAÑO CONCRETO CORROSION Tipo de daño/calificación Calificación Insign ificant e(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) D6DC45 Daño concreto/corrosión Este tipo de daño consiste en deficiencias en la durabilidad del concreto, producida por la carbonatación o baja de pH. Esto genera que el recubrimiento del concreto no proteja adecuadamente el acero de refuerzo, generando problemas de corrosión. Su deterioro también puede deberse a un alto contenido de sulfatos y cloruros en puentes construidos en zonas con ambientes agresivos. Esto se refleja a través de fisuras no estructurales o cambios de color cerca de donde haya indicios de humedad. La fractura del acero de refuerzo y pretensado puede ser causada por corrosión, sobrecarga, daño por fuego o impacto, siendo la corrosión la causa más frecuente. La fractura del acero de refuerzo o pretensado resulta en una pérdida significativa de resistencia que debe corregirse lo antes posible para evitar un colapso estructural. La fractura del refuerzo convencional debido a la corrosión generalmente estaría precedida por una pérdida significativa de sección y estaría acompañada de signos como manchas de óxido, fisuras y delaminación. Sin embargo, con detalles ocultos es posible que se produzca corrosión sin estos signos superficiales. La corrosión de los tendones tensados dentro de los conductos postensados presenta un problema particular, ya que puede haber poca evidencia de corrosión visible en la superficie. El uso de acero pretensado susceptible a la corrosión por tensión o al agrietamiento por hidrógeno puede resultar en una fractura frágil que puede conducir a una pérdida catastrófica de resistencia estructural ( Véase (Duratinet, 2013)) No presen ta Concreto con inicios de carbonatació n sin pérdida de sección del acero de refuerzo principal. Concreto parcialmente carbonatado sin pérdida de sección del ac",
