    "extracto": "E1DE43 D. ESTRUCTURAL. Y/O DEFICIENCIAS Tipo de daño/calificaci ón Calificación Insignifica nte(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) E1DE43 D. estructural. y/o deficiencias Deficiencias en su diseño estructural, que implican que dicho componente no tenga la capacidad de absorber las deformaciones verticales y horizontales entre la zona de acceso y el tablero del puente Esto sucede cuando el tipo de junta seleccionado no es el adecuado, lo cual depende del tipo de puente, su tipología y longitud). Para ello, se deben tener en cuenta los movimientos relativos en la construcción y en el diseño, de acuerdo con lo especificado en los numerales 14.5.3.1 y 145.32 de la norma CCP-14. Los materiales seleccionados deben ser compatibles desde el punto de vista elástico, térmico y químico. Los elastómero o neoprenos para sellos de juntas deben proporcionar una vida útil no menor a 25 años. Hay que asegurar que cada extremo en concreto reforzado (zona de estribo con tablero o tablero con tablero en zona de pilas), donde se instale la junta de dilatación, este en buen estado. En caso de que el diseño lo indique, puede ser indispensable la construcción en cada extremo de un bloque o viga longitudinal que garantice la estabilidad y buen comportamiento de la zona donde se instala la junta, incluyendo una correcta nivelación, apertura de junta, etc. La viga longitudinal debe contar con sus respectivos flejes y barras longitudinales, fijando con epóxico los anclajes debidamente diseñados. El detallado de la junta debe permitir el acceso a las juntas por debajo del tablero y proporcionar área suficiente para el mantenimiento asegurando que no se generen daños a la estructura por filtración agua, químicos y desechos de la calzada ( Véase (IDU/PUJ, 2017c)) No presenta Menor del 10% de la junta esta suelta o con pérdida de sello. Del 10-20% de la junta esta suelta. O hay movi",
