    "pagina": 82,
    "extracto": "E1DE55 D. ESTRUCTURAL. BARANDAS Tipo de daño/calificaci ón Calificación Insignific ante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) E1DE55 D. estructural. barandas Las barandas y barreras de tráfico deben tener el propósito principal de contener y redireccionar los vehículos que circulan por el tablero del puente. Se debe asegurar que estos elementos, basados en la aplicación de la sección 13 norma CCP-14(INVIAS/AIS, 2014) cualquiera que sea el tipo y/o combinación, sean estructural y geométricamente resistentes al choque. La altura mínima de las barandas y barreras de tráfico vehicular tipo TL-4, que es el más aplicable para Colombia, debe ser de 813 mm según el numeral 13.7.3.2 de la norma CCP-14(INVIAS/AIS, 2014). La carga viva de diseño de barandas peatonales debe ser de 0.73 N/mm actuando simultáneamente en sentido transversal y vertical. Además, cada elemento longitudinal que hace parte de la baranda debe estar diseñado para una carga concentrada de 0.89 kN, la cual debe actuar simultáneamente con las cargas previamente indicadas en cualquier punto y dirección en la parte superior del elemento longitudinal.(IDU/PUJ, 2017a) No presenta Para las partes en concreto : Anchos de fisura menores a 0.1mm que indican que son no estructurales. Para las partes en concreto : Presenta fisuras con espesores entre 0.1 a 0.2 mm que indican esfuerzos altos fraguado u otro problema durante su construcción ( tecnología del concreto) . Para las partes de acero hay una pérdida de sección del acero por corrosión mayor del entre el 7.5 y 10% de su espesor Para las partes en concreto: Presenta fisuras con espesores entre 0.2 a 0.4 mm que indican esfuerzos altos y problema con respecto a su capacidad de carga Para las partes de acero hay una pérdida de sección del acero por corrosión entre el 7.5 y 10% de su espesor. Para ambos materiales puede presentarse desalineamiento o dist",
