    "extracto": "E2RO78 Rotación en planta de pilas TIPO DE DAÑO CALIFICACIÓN INSIGNIFICANT E (0) LIGERO (1) LEVE (2) FUERTE (3) SEVERO (4) EXTREMO (5) E2RO7 8 Rotació n en planta en pilas Rotación del eje del conjunto de pilas con el eje longitudinal del puente. La pila o conjunto de pilas no presenta rotación en planta. La pila o conjunto de pilas presenta una rotación entre 0 y 5° respecto a su eje longitudina l. La pila o conjunto de pilas presenta una rotación entre 5 y 10° respecto a su eje longitudina l. Se pueden observar fisuras en el cuerpo del elemento. La pila o conjunto de pilas presenta una rotación entre 10 y 15° respecto a su eje longitudina l. Se pueden observa grietas en el cuerpo del elemento. La pila o conjunto de pilas presenta una rotación entre 15 y 20° respecto a su eje longitudina l. Se pueden observar grietas y deformació n en el cuerpo del elemento. La pila o conjunto de pilas presenta una rotación mayor a 20° respecto a su eje longitudinal. Se pueden observar grietas y deformacione s en el cuerpo del elemento y asentamiento de la misma.",
