    "nombre": "Agrietamiento por fatiga en conexiones con remaches o pernos",
    "area": "Estabilidad",
    "pagina": 145,
    "extracto": "E3FA152 Agrietamiento por fatiga en conexiones con remaches o pernos CLASIFICACIÓN Calificación Insignificante (0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) E3FA152 Agrietamiento por fatiga en conexiones con remaches o pernos. Agrietamiento por fatiga en conexiones con remaches o pernos. Puede presentarse en el orificio por perforaciones con superficie irregular. Sin fisuras en el detalle evaluado. Posible presencia de fisuración en platina de conexión ya que se evidencia daño en el recubrimiento y con oxidación leve en cercanía de los remaches o pernos. Al remover el recubrimiento con cepillo se identifica mediante inspección visual con equipos de magnificación (lupa o microscopio portátil) que hay fisuras en alguna zona de la platina de conexión. Solo afectando uno o dos de los remaches en el detalle. Se evidencia visualmente la fisura que afecta la platina de conexión en hasta un máximo del 20% de los remaches en el ángulo. No se aprecia actividad en la grieta o esta se encuentra arrestada. Se evidencia visualmente la fisura y esta afecta el detalle de conexión a un máximo del 40% de los remaches en la cartela. Se puede determinar que la fisura por fatiga se encuentra activa. Las fisuras detectadas deben ser reportadas y reparadas inmediatamente. Se evidencia visualmente la fisura que afecta el detalle de conexión en más del 40% de los remaches en esta. Se puede determinar que la fisura por fatiga se encuentra activa. Las fisuras detectadas deben ser reportadas y reparadas inmediatamente.",
