    "area": "Estabilidad",
    "pagina": 147,
    "extracto": "E3FA153 Alma discontinua o con detalle de pasa ratón CLASIFICACIÓN Calificación Insignificante (0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) E3FA153 Alma discontinua o con detalle de pasa ratón. Alma discontinua o con detalle de pasa ratón. Grieta por fatiga en alma o aleta, iniciada en la punta de soldadura de filete. Sin fisuras en el detalle evaluado. Posible presencia de fisuración en cercanías de las soldaduras en alma cortada en detalle de pasaratón ya que se evidencia daño en el recubrimiento y con oxidación leve en zona del cordón de soldadura. Al remover el recubrimiento con cepillo se identifica mediante inspección visual con equipos de magnificación (lupa o microscopio portátil) que hay fisuras en un tramo de la soldadura de conexión sin afectar el metal base. Se evidencia a simple vista la fisura que afecta la soldadura de conexión hasta en un 50% el espesor de esta. No se aprecia actividad en la grieta o esta se encuentra arrestada. Fisura se evidencia visualmente y afecta el metal base sin avanzar más allá del 50% de su espesor. Se puede determinar que la fisura por fatiga se encuentra activa. Las fisuras detectadas deben ser reportadas y reparadas inmediatamente. Presencia de fisuras con trayectorias perpendicular, longitudinal o diagonal (45°) con avance en el patín y el alma de la viga evaluada. Se puede determinar que la fisura por fatiga se encuentra activa. Las fisuras detectadas deben ser reportadas y reparadas inmediatamente.",
