    "extracto": "E3FL107 Pérdida o desgaste de elementos en conexiones pérdida o desgaste de elementos en conexiones Tipo de daño/calificación Calificación Insignifi cante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) E3FL107 Pérdida o desgaste de elementos en conexiones pérdida o desgaste de elementos en conexiones Pérdida o desgate de pernos, remaches o tornillos en las conexiones de los arriostramientos o contraventeos en tablero de puentes de vigas de acero , armaduras, arcos de acero, colgantes, atirantados, etc. No presenta Cuando se presentan pérdidas menores al 10% de los tornillos/pern os/remaches en conexiones de elemento secundarios Cuando se presentan pérdidas menores al 5 % de los tornillos/pernos/remaches en conexiones de elemento principales. Cuando se presentan pérdida entre el 10 al 15% de los tornillos/pernos/remaches en conexiones de elemento secundarios Cuando se presentan pérdida entre del 5 al 10% de los tornillos/perno s/remaches en conexiones de elemento principales. Cuando se presentan pérdida entre el 15 al 30% de los tornillos/perno s/remaches en conexiones de elemento secundarios Cuando se presentan pérdida entre del 10 al 20% de los tornillos/pernos/re maches en conexiones de elemento principales. Cuando se presentan pérdida entre el 30 al 50% de los tornillos/pernos/re maches en conexiones de elemento secundarios Cuando se presentan pérdida de más del 20% de los tornillos/pernos/remaches en conexiones de elemento principales. Cuando se presentan pérdida de más del 50% de los tornillos/pernos/remaches en conexiones de elemento secundarios",
