    "pagina": 183,
    "extracto": "E6CO57 Grietas por corrosión Tipo de daño/calificaci ón Calificación Insignific ante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) E6CO57 Grietas por corrosión La naturaleza expansiva de los procesos de corrosión conduce a fuerzas de ruptura que actúan sobre el recubrimiento del concreto que provocan grietas, deslaminación y eventuales desconchados. Las grietas por corrosión generalmente se identifican debido a la presencia de manchas de óxido dentro y alrededor de las grietas que emanan del refuerzo corrosivo. Las grietas por corrosión generalmente están alineadas con el refuerzo. Fuente: (Duratinet, 2013) No presenta Cuando de observan grietas paralelas al refuerzo y con machas de oxido con un espesor menor de 0.1mm Cuando de observan grietas paralelas al refuerzo y con machas de oxido con un espesor entre el 0.1-0.2 mm Cuando de observan grietas paralelas al refuerzo y con machas de oxido con un espesor entre el 0.2-0.4 mm Cuando de observan grietas paralelas al refuerzo y con machas de oxido con un espesor entre el 0.4 a 0.6 mm Cuando de observan grietas paralelas al refuerzo y con machas de oxido con un espesor mayor a 0.6 mm Fuentes: (Duratinet, 2013)",
    "severidades": {
      "0": "Insignificante / No presenta",
      "1": "Ligero",
      "2": "Leve",
      "3": "Fuerte",
      "4": "Severo",
      "5": "Extremo"
    },
