    "extracto": "S1NS35 Situaciones en el acceso del puente no señalizadas Tipo de daño/calificación Calificación Insignificante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) S1NS35 Situaciones en el acceso del puente no señalizadas Situaciones en los accesos a los puentes como presencia de zonas escolares (SP-47), intersecciones (SP-11 a SP-15) y sitio de paraderos establecido (sr-40), deben estar debidamente señalizadas. (min. 20 m. antes del tablero del puente en ambos sentidos) Se encuentran señalizadas todas las situaciones existentes en los accesos del puente. Se encuentran señalizadas parcialmente las situaciones existentes en los accesos del puente. No se encuentran señalizadas las situaciones existentes en los dos accesos del puente.",
