    "area": "Seguridad vial",
    "pagina": 204,
    "extracto": "S5FL149 Inexistencia de señales reglamentarias para puentes largos y/o estrechos. Tipo de daño/calificación Calificación Insignificante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) S5FL149 Inexistencia de señales reglamentarias para puentes largos y/o estrechos. Para el caso de los puentes largos debe prohibirse la circulación de maquinaria agrícola SR-24, la circulación de vehículos de tracción animal SR-25 y la circulación de vehículos de mano SR-51; y en algunos casos para impedir que se conduzca a una velocidad tan baja que entorpezca el tráfico sobre el puente se establece una velocidad mínima permitida SR-30A. Asimismo, para el caso de puentes estrechos debe existir la señal SR-49 para dar preferencia al sentido contrario del tránsito. Fuente: (Minitransporte/PUJ, 2009) Se encuentran todas las señales reglamentarias requeridas. Se encuentran parcialmente las señales reglamentarias requeridas. No se encuentran ninguna de las señales reglamentarias requeridas.",
