    "extracto": "S1RE34 Reducción de calzada no señalizada. Tipo de daño/calificación Calificación Insignificante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) S1RE34 Reducción de calzada no señalizada. Se debe advertir al conductor la proximidad a un puente cuyo ancho es inferior al ancho de corona de la vía mediante la señal SP-36, que deberá complementarse con la señal reglamentaria de ancho máximo permitido SR-33, cuando éste sea inferior a tres cuartos del ancho de la calzada; además ésta deberá ser complementada con la señal SP-51, para advertir al conductor que más adelante en la vía existe una restricción de ancho que puede afectar a ciertos vehículos. Fuente: (Minitransporte/PUJ, 2009) La reducción de calzada presenta la señalización adecuada. La reducción de calzada se encuentra parcialmente señalizada. La reducción de calzada no presenta señalización",
