    "extracto": "S5FL134 Inexistencia de señales informativas en el puente. Tipo de daño/calificación Calificación Insignificante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) S5FL134 Inexistencia de señales informativas en el puente. Las señales de localización, tienen como función indicar límites jurisdiccionales de ciudades, identificar ríos, puentes, etc., que sirven de orientación a los usuarios. Cuando estas señales informativas contengan nombres de ríos o puentes, el tamaño de las letras podrá ser de 15 cm aun cuando, dada la velocidad de la vía, se requiera un tamaño superior. Excepcionalmente, sólo cuando una localidad o lugar sea considerado como atractivo turístico de la zona, y su nombre figure en una misma placa panel junto a señales de atractivo turístico, el color de fondo de toda la señal podrá ser de color marrón y las letras y símbolos de color blanco. Fuente: [Manual de Señalización 2015 - M.T.] Se encuentran todas las señales informativas requeridas. Se encuentran parcialmente las señales informativas requeridas. No se encuentran ninguna de las señales informativas requeridas.",
