    "codigo": "S5FL137",
    "nombre": "Señales verticales duplicadas, desniveladas y/o mal orientadas. 208 .",
    "area": "Seguridad vial",
    "pagina": 208,
    "extracto": "S5FL137 Señales verticales duplicadas, desniveladas y/o mal orientadas. . Tipo de daño/calificación Calificación Insignificante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) S5FL137 Señales verticales duplicadas, desniveladas y/o mal orientadas. “Para que las señales puedan ser percibidas por los conductores es preciso que éstas se ubiquen dentro de su cono de atención, esto es, dentro de 10° respecto de su eje visual, evitando instalarlas alejadas de la calzada, demasiado elevadas o muy abajo respecto del nivel de ésta”. “Para lograr una buena visibilidad nocturna de las señales se recomienda ubicarlas en lugares donde puedan ser adecuadamente iluminadas por los focos de los vehículos”. La altura de la señal debe asegurar su visibilidad, por ello la elevación correcta queda definida, en primer lugar, por los factores que podrían afectar dicha visibilidad, como altura de vehículos en circulación o estacionados, etc.; en segundo lugar, debe considerarse la geometría horizontal y vertical de la vía. Fuente: [Manual de Señalización 2015 - M.T.]. Algunas veces, se generan contratos de señalización que colocan nuevas señales, pero no retiran las existentes, así que pueden existir señales duplicadas, restando credibilidad a la señalización. Señales verticales existentes no duplicadas, niveladas y/o bien orientadas Señales verticales existentes duplicadas, con la altura correcta y bien orientadas Señales verticales desniveladas y/o mal orientadas, aunque no presenten duplicidad. Señales verticales existentes duplicadas, desniveladas y/o mal orientadas.",
