    "extracto": "S5FL139 Inexistencia de infraestructura para tráfico no motorizado. S5FL139 Inexistencia de infraestructura para tráfico no motorizado. Existencia de facilidades para el tránsito de peatones y ciclistas sobre el puente. Inexistencia de facilidades para el tránsito de peatones y ciclistas sobre el puente. *No se presentan calificaciones intermedias en esta rúbrica, entendiendo la gran vulnerabilidad de los actores no motorizados, que, ante la inexistencia de facilidades para su circulación, se ven obligados a compartir la calzada con el tránsito vehicular. Tipo de daño/calificación Calificación Insignificante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5)",
