    "area": "Seguridad vial",
    "pagina": 213,
    "extracto": "S5FL140 Deficiente transición de luminosidad en el puente. S5FL140 Deficiente transición de luminosidad en el puente. La transición de luminosidad entre los accesos y el tablero de los puentes, es un aspecto relevante de seguridad vial; si bien es cierto la iluminación mejora la visibilidad de los conductores mientras circulan dentro del puente, los usual es que las vías de acceso a los puentes no estén iluminadas, así que recobra importancia la transición que se realice con el fin de evitar cambios bruscos de luminosidad y permitir que el conductor se adapte. Presenta la transición de luminosidad adecuada entre los accesos y el tablero del puente. Presenta la transición de luminosidad adecuada sólo en un acceso del puente. No presenta transición de luminosidad entre los accesos y el tablero. Tipo de daño/calificación Calificación Insignificante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5)",
