    "area": "Seguridad vial",
    "pagina": 214,
    "extracto": "S1RE32 Abrupta reducción en la velocidad al acceso del puente. S1RE32 Abrupta reducción en la velocidad al acceso del puente. No debe existir disminución obligada de la velocidad el acceder al puente, ni por desnivel o abertura de las juntas de expansión, ni por deficiente visibilidad del alineamiento horizontal y vertical del puente. No existe reducción de la velocidad de operación La reducción en la velocidad de operación es de menor de 10 k/h. La reducción en la velocidad de operación es entre 10 a 20 k/h. La reducción en la velocidad de operación es entre 20 a 30 k/h. La reducción en la velocidad de operación es de mayor de 30 k/h. Prácticamente el tráfico tiene que detenerse en la aproximación al puente",
