    "extracto": "S1MA41 Estado funcional de infraestructuras para tráfico no motorizado. Tipo de daño/calificación Calificación Insignificante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) S1MA41 Estado funcional de infraestructuras para tráfico no motorizado. Las dimensiones de los andenes y ciclorutas, deben soportar la demanda de tráfico de peatones y ciclistas existente en el puente; asimismo, dichas facilidades para peatones y ciclistas, deben estar debidamente iluminadas y con sus bordillos. Se sugiere calificar el primer aspecto en diversas condiciones de demanda (día hábil, día de mercado, día de fiestas especiales, etc.), y el último aspecto mediante inspecciones nocturnas. Los andenes dentro del puente soportan adecuadamente los tráficos de peatones y ciclistas (estos no están obligados a transitar por la calzada vehicular); además presentan aceptable iluminación. . Los andenes dentro del puente soportan adecuadamente los tráficos de peatones y ciclistas, pero no están iluminados. Los andenes dentro del puente no soportan adecuadament e los tráficos de peatones y ciclistas (estos están obligados a transitar por la calzada vehicular); además no presentan iluminación.",
