    "area": "Seguridad vial",
    "pagina": 216,
    "extracto": "S1MA24 Mal estado de elementos del puente. S1MA24 Mal estado de elementos del puente. Elementos de los puentes como cables, pendolones, torres o elementos de armadura, juntas, láminas de losas, etc.; no deben presentar daños que puedan afectar el normal y seguro transitar de peatones y ciclistas dentro de los andenes del puente. Los andenes del puente son seguros para el tránsito de ciclistas y peatones. Los andenes del puente son inseguros para el tránsito de ciclistas y peatones (los elementos del puente presentan al menos un daño que afecta la seguridad de ciclistas y peatones) *No se presentan calificaciones intermedias en esta rúbrica, entendiendo la gran vulnerabilidad de los actores no motorizados, que ante un sólo daño de los elementos del puente, pueden poner en riesgo su vida; por ej. la abertura de una junta es una amenaza latente para un ciclista o peatón. Tipo de daño/calificación Calificación Insignificante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5)",
