    "pagina": 218,
    "extracto": "S5FL135 Deficiente estado de las señales verticales Tipo de daño/calificación Calificación Insignificante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) S5FL135 Deficiente estado de las señales verticales La señalización limpia, legible, visible, en buen estado y pertinente inspira respeto en los conductores y peatones. Cualquier señal que se encuentra deteriorada, dañada o rayada, solo contribuye a su descrédito y al de la entidad responsable de su mantenimiento, y constituye además un estímulo para actos vandálicos. Fuente: [Manual de Señalización 2015 - M.T.] Buen estado de las señales verticales existentes. Menos del 20% de las señales verticales existentes se encuentran en mal estado. Entre el 20% y el 40% de las señales verticales existentes se encuentran en mal estado. Entre el 40% y el 60% de las señales verticales existentes se encuentran en mal estado. Entre el 60% y el 80% de las señales verticales existentes se encuentran en mal estado. Más del 80% de las señales verticales existentes se encuentran en mal estado.",
