    "extracto": "S5FL141 Ambigüedad en la señalización vertical. Tipo de daño/calificación Calificación Insignificante(0) Ligero(1) Leve(2) Fuerte(3) Severo(4) Extremo(5) S5FL141 Ambigüedad en la señalización vertical. “Toda señal debe transmitir un mensaje inequívoco al usuario del sistema vial…Las condiciones similares deben siempre anunciarse con el mismo tipo de señal” cualquier señal que permanece en la vía sin que se justifique… solo contribuye a su descrédito y al de la entidad responsable de su mantenimiento…” Fuente: [Manual de Señalización 2015 - M.T.] La señalización vertical del puente es consistente, no presenta ambigüedades y está de acuerdo con el Manual. La señalización vertical del puente no está de acuerdo con el Manual de señalización colombiano La señalización vertical del puente presenta ambigüedades que pueden generar mensajes equívocos a los conductores La señalización vertical del puente no es consistente, presenta ambigüedades y no está de acuerdo con el Manual.",
