    "pagina": 233,
    "extracto": "DR2-6 DEFECTOS ESTRUCTURALES EN TORRES DR2-6 Defectos estructurales en torres Bajo Medio Alto Cuando en una o dos partes de los elementos principales con pandeo local, pandeo general y distorsión. También agrietamientos y fractura. Igualmente, movimientos laterales excesivos. Cuando se presentan en algunas partes de los elementos principales con pandeo local, pandeo general y distorsión. También agrietamientos y fractura. Igualmente, movimientos laterales excesivos. Cuando se presentan en gran parte de los elementos principales con pandeo local, pandeo general y distorsión. También agrietamientos y fractura. Igualmente, movimientos laterales excesivos. 4.18 DR4-1 EROSIÓN/SOCAVACIÓN EN TALUDES DR4-1 Erosión/socavación en taludes Bajo Medio Alto Derrumbamiento mínimo del talud adyacente que deja expuesta una parte la cimentación del estribo y/o aleta. Derrumbamiento medio del talud adyacente que deja expuesta una parte de la cimentación del estribo y/o aleta. Derrumbamiento importante del talud adyacente que deja expuesta gran parte de la cimentación del estribo y/o aleta.",
