    "extracto": "DR3-1 EXISTENCIA DE FISURAS EN ELEMENTOS DE ARCO DE MAMPOSTERÍA DR3-1 Existencia de fisuras en elementos de arco de mampostería Bajo Medio Alto Cuando son fisuras de abertura pequeña: Cuando se trata de fisuras que afectan una parte del área del arco, independiente del espesor de las fisuras. Cuando son fisuras de abertura media: Cuando se trata de fisuras que afectan una parte del área del arco, independiente del espesor de las fisuras. Cuando son fisuras de abertura importante: Cuando se trata de fisuras que afectan gran parte del área del arco, independiente del espesor de las fisuras.",
