    "extracto": "DR3-2 ROTURA DE LOS HILOS O ALAMBRES EN LOS CABLES PRINCIPALES (CATENARIA). DR3-2 Rotura de los hilos o alambres en los cables principales (catenaria). Bajo Medio Alto Cuando se presenta la rotura de un hilo de alambre en cables principales. Cuando se presenta la rotura de uno o dos hilos de alambre en cables principales. Cuando se presenta desajuste o perdida parcial de los tornillos/pasadores principales de las correspondientes uniones de los pendolones con catenaria o con las vigas de rigidez. Cuando se presenta la rotura de varios hilos de alambre en cables principales. Cuando se presenta desajuste o perdida de los tornillos/pasadores principales de las correspondientes uniones de los pendolones con catenaria o con las vigas de rigidez.",
