    "pagina": 236,
    "extracto": "DR3-3 AGRIETAMIENTO Y/O APLASTAMIENTO EN LA ZONA DONDE DESCANSA EL APARATO DE APOYO. DR3-3 Agrietamiento y/o aplastamiento en la zona donde descansa el aparato de apoyo. Bajo Medio Alto Cuando se evidencia presencia de fisuras menores ante en las esquinas de las vigas o estribos o viga cabezal de pila. Cuando se evidencia presencia de algunas fisuras ante en las esquinas de las vigas o estribos o viga cabezal de pila. Cuando hay desconches menores debajo de los aparatos de apoyo por falla o por aplastamiento del concreto en los estribos y las pilas. Cuando se evidencia presencia importante de fisuras ante en las esquinas de las vigas o estribos o viga cabezal de pila. Cuando hay desconches mayores debajo de los aparatos de apoyo por falla o por aplastamiento del concreto en los estribos y las pilas.",
