    "extracto": "DR4-3 PRESENCIA DE ZONAS DE ESTANCAMIENTO O DE ALTA TURBULENCIA DEL FLUJO O ZONAS CERCANAS A LOS ESTRIBOS. DR4-3 Presencia de zonas de estancamiento o de alta turbulencia del flujo o zonas cercanas a los estribos. Bajo Medio Alto Se observan zonas de estancamiento pequeñas, ubicadas en cercanías de los estribos. Se observan zonas de baja turbulencia en regiones próximas a los estribos del puente. Se observan zonas de alta turbulencia en regiones próximas a los estribos o pilas del puente. Se observa un cambio sustancial del color del agua debido al transporte de sedimento.",
