    "pagina": 245,
    "extracto": "DR4-10 MOVIMIENTO/INESTABILIDAD ACCESOS SUBESTRUCTURA DR4-10 Movimiento/inestabilidad accesos subestructura Bajo Medio Alto Los taludes del valle del río no presentan inestabilidad visible. No se observa material colapsado de la ladera del cauce. Los taludes del valle del río presentan fisuras grandes, se identifica algún mecanismo de falla del talud que se puede activar en épocas de precipitaciones importantes. Se encuentra material colapsado de la ladera en la pata del talud. Los taludes del valle del río son altamente inestables, se observa la caída de material durante la visita. Se encuentra una gran cantidad de material colapsado de la ladera en la pata del talud.",
