    "extracto": "DR3-9 FISURAS EN PENDOLONES Y CONECTORES POR FATIGA INDUCIDA POR VIBRACIONES DR3-9 Fisuras en pendolones y conectores por fatiga inducida por vibraciones Bajo Medio Alto Posible fisura en el elemento de conexión en una parte de la sección. Fisura se evidencia visualmente en el elemento de conexión en una parte de la sección. Fisura se evidencia visualmente en el elemento de conexión en gran parte de la sección. Se puede determinar que la fisura por fatiga se encuentra activa. Las fisuras detectadas deben ser reportadas y reparadas inmediatamente.",
